import { randomBytes, scrypt, timingSafeEqual, type ScryptOptions } from 'node:crypto';

/**
 * Device secrets: generation, hashing and verification.
 *
 * Hashing is scrypt from Node's built-in `crypto` (no native add-on to build).
 * Secrets are long random strings generated by `device:create`, not
 * passwords people chose, so the work factor guards against a leaked hash
 * table rather than dictionary attacks; N=2^14, r=8, p=1 costs about 16 MB
 * and tens of milliseconds per check. Parameters are stored with each hash so
 * they can be raised later without breaking existing devices.
 *
 * Encoded form: `scrypt$v=1$n=16384,r=8,p=1$<salt base64url>$<hash base64url>`.
 */

export const SCRYPT_DEFAULTS = { n: 16_384, r: 8, p: 1 } as const;
const KEY_LENGTH = 32;
const SALT_LENGTH = 16;
/** Accepted parameter ranges when reading a stored hash, so a bad row cannot exhaust memory. */
const LIMITS = { nMin: 1_024, nMax: 131_072, rMax: 16, pMax: 4 } as const;

/** Device secrets we accept on the wire. Generated ones are 40 characters. */
export const SECRET_MIN_LENGTH = 16;
export const SECRET_MAX_LENGTH = 256;
export const GENERATED_SECRET_LENGTH = 40;

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

/**
 * A random secret of letters and digits only. Device web forms vary in which
 * symbols they accept (UNVERIFIED for the VS135 password field), so we avoid
 * symbols and get the strength from length: 40 characters ≈ 238 bits.
 */
export function generateDeviceSecret(length: number = GENERATED_SECRET_LENGTH): string {
  if (!Number.isInteger(length) || length < SECRET_MIN_LENGTH || length > 128) {
    throw new RangeError(`length must be an integer from ${SECRET_MIN_LENGTH} to 128`);
  }
  // Rejection sampling keeps every character equally likely.
  const limit = 256 - (256 % ALPHABET.length);
  let out = '';
  while (out.length < length) {
    for (const byte of randomBytes(length * 2)) {
      if (byte < limit && out.length < length) out += ALPHABET.charAt(byte % ALPHABET.length);
    }
  }
  return out;
}

interface ParsedHash {
  n: number;
  r: number;
  p: number;
  salt: Buffer;
  hash: Buffer;
}

function scryptAsync(secret: string, salt: Buffer, params: { n: number; r: number; p: number }) {
  const options: ScryptOptions = {
    N: params.n,
    r: params.r,
    p: params.p,
    maxmem: 256 * params.n * params.r * params.p,
  };
  return new Promise<Buffer>((resolve, reject) => {
    scrypt(secret.normalize('NFC'), salt, KEY_LENGTH, options, (error, key) => {
      if (error) reject(error);
      else resolve(key);
    });
  });
}

function isPowerOfTwo(value: number): boolean {
  return Number.isInteger(value) && value > 0 && (value & (value - 1)) === 0;
}

export function parseSecretHash(encoded: string): ParsedHash | null {
  const parts = encoded.split('$');
  if (parts.length !== 5 || parts[0] !== 'scrypt' || parts[1] !== 'v=1') return null;
  const params = /^n=(\d{1,7}),r=(\d{1,2}),p=(\d)$/.exec(parts[2] ?? '');
  if (!params) return null;
  const n = Number(params[1]);
  const r = Number(params[2]);
  const p = Number(params[3]);
  if (!isPowerOfTwo(n) || n < LIMITS.nMin || n > LIMITS.nMax) return null;
  if (r < 1 || r > LIMITS.rMax || p < 1 || p > LIMITS.pMax) return null;
  const b64url = /^[A-Za-z0-9_-]+$/;
  if (!b64url.test(parts[3] ?? '') || !b64url.test(parts[4] ?? '')) return null;
  const salt = Buffer.from(parts[3] ?? '', 'base64url');
  const hash = Buffer.from(parts[4] ?? '', 'base64url');
  if (salt.length !== SALT_LENGTH || hash.length !== KEY_LENGTH) return null;
  return { n, r, p, salt, hash };
}

export async function hashDeviceSecret(secret: string): Promise<string> {
  if (secret.length < SECRET_MIN_LENGTH || secret.length > SECRET_MAX_LENGTH) {
    throw new RangeError('secret length out of range');
  }
  const salt = randomBytes(SALT_LENGTH);
  const hash = await scryptAsync(secret, salt, SCRYPT_DEFAULTS);
  const { n, r, p } = SCRYPT_DEFAULTS;
  return `scrypt$v=1$n=${n},r=${r},p=${p}$${salt.toString('base64url')}$${hash.toString('base64url')}`;
}

/**
 * A fixed hash with the default parameters, used when there is no real hash to
 * check against (unknown device, empty rotation slot) so every request does
 * the same amount of work. Its secret is random and never stored.
 */
let dummyHash: Promise<string> | undefined;
export function getDummyHash(): Promise<string> {
  dummyHash ??= hashDeviceSecret(generateDeviceSecret());
  return dummyHash;
}

/**
 * Constant-time check of a presented secret against an encoded hash. Always
 * runs one scrypt with the hash's parameters (or the defaults if the hash
 * cannot be parsed) before answering.
 */
export async function verifyDeviceSecret(secret: string, encoded: string): Promise<boolean> {
  const real = parseSecretHash(encoded);
  const parsed = real ?? parseSecretHash(await getDummyHash());
  if (parsed === null) return false;
  const acceptable = secret.length >= 1 && secret.length <= SECRET_MAX_LENGTH;
  const candidate = await scryptAsync(acceptable ? secret : '', parsed.salt, parsed);
  const match = timingSafeEqual(candidate, parsed.hash);
  return real !== null && acceptable && match;
}
